SELECT sku, name, pack
FROM store.products
WHERE name ILIKE '%atta%' OR name ILIKE '%wheat%';

SELECT rrn, status, initiated_ts, status_ts
FROM payments.psp_upi_report
WHERE rrn IN (
    SELECT rrn FROM payments.upi_refunds 
    WHERE requested_ts >= '2026-06-01' AND requested_ts < '2026-07-01'
);

SELECT SUM(units_sold) AS total_units
FROM store.daily_sales
WHERE date >= '2026-06-01' AND date <= '2026-06-30';

SELECT *
FROM store.shelf_audits
LIMIT 20;

SELECT table_name
FROM information_schema.tables
WHERE table_schema = 'store' AND table_name LIKE '%job%' OR table_name LIKE '%task%' OR table_name LIKE '%schedule%';

SELECT DISTINCT sku_scanned
FROM store.pos_lines
WHERE sku_scanned ILIKE '%bag%' OR sku_scanned ILIKE '%carry%';

SELECT sku, name
FROM store.products
ORDER BY sku;

SELECT *
FROM warehouse.shipments
LIMIT 10;

SELECT *
FROM store.store_orders
LIMIT 10;

SELECT sku, name
FROM store.products
WHERE name ILIKE '%bread%' OR sku ILIKE '%bread%';

SELECT *
FROM store.forecasts
LIMIT 20;

SELECT DISTINCT sku
FROM store.forecasts
WHERE sku ILIKE '%bread%';

SELECT * FROM warehouse.shipping_notice_lines
WHERE sku = 'RICE-SM-5KG'
  AND ship_notice_id IN (
    SELECT ship_notice_id FROM warehouse.shipping_notice_lines
    WHERE sku = 'RICE-SM-5KG'
  );

SELECT * FROM warehouse.shipments
WHERE shipment_id >= 'SHP-260610' AND shipment_id <= 'SHP-260615'
ORDER BY shipment_id;

SELECT COUNT(*) AS products_above_100
FROM store.products
WHERE selling_price > 100;

